# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

FULL = "09:00-17:00"

def _gaps(worked, hours=FULL):
    spans = [parse_span(text) for text in worked]
    return find_gaps(spans, parse_span(hours))

class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        result = _gaps(
            ["09:00-12:00", "13:00-17:00"]
        )
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, want)

    def test_gaps_at_both_ends(self):
        result = _gaps(["10:00-11:00"], "09:00-12:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-12:00 (60 min)",
        ])

    def test_full_coverage_has_no_gaps(self):
        result = _gaps(
            ["09:00-13:00", "12:00-17:00"]
        )
        self.assertEqual(result, [])

    def test_nobody_working_is_one_gap(self):
        result = _gaps([], "09:00-10:00")
        want = ["gap 09:00-10:00 (60 min)"]
        self.assertEqual(result, want)

    def test_span_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            _gaps(["08:00-10:00"])
